changeSet.sql:
ALTER TABLE zc_assessment
  ADD CONSTRAINT fk_zc_assessment_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_assessment
  ADD CONSTRAINT fk_zc_assessment_enrolment FOREIGN KEY (tenant_id, enrolment_id)
    REFERENCES zc_enrolment (tenant_id, id);
ALTER TABLE zc_assessment
  ADD CONSTRAINT fk_zc_assessment_template_version FOREIGN KEY (tenant_id, template_version_id)
    REFERENCES zc_assessment_template_version (tenant_id, id);

ALTER TABLE zc_assessment_response
  ADD CONSTRAINT fk_zc_assessment_response_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_assessment_response
  ADD CONSTRAINT fk_zc_assessment_response_assessment FOREIGN KEY (tenant_id, assessment_id)
    REFERENCES zc_assessment (tenant_id, id);

ALTER TABLE zc_risk_classification
  ADD CONSTRAINT fk_zc_risk_classification_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_risk_classification
  ADD CONSTRAINT fk_zc_risk_classification_enrolment FOREIGN KEY (tenant_id, enrolment_id)
    REFERENCES zc_enrolment (tenant_id, id);
ALTER TABLE zc_risk_classification
  ADD CONSTRAINT fk_zc_risk_classification_assessment FOREIGN KEY (tenant_id, assessment_id, enrolment_id)
    REFERENCES zc_assessment (tenant_id, id, enrolment_id);
ALTER TABLE zc_risk_classification
  ADD CONSTRAINT fk_zc_risk_classification_overrides FOREIGN KEY (tenant_id, overrides_id, enrolment_id)
    REFERENCES zc_risk_classification (tenant_id, id, enrolment_id);

CREATE TRIGGER trg_zc_assessment_pins
  BEFORE UPDATE ON zc_assessment
  FOR EACH ROW EXECUTE FUNCTION zc_forbid_pinned_change(
    'trg_zc_assessment_pins', 'enrolment_id', 'template_version_id');
CREATE TRIGGER trg_zc_assessment_touch BEFORE UPDATE ON zc_assessment FOR EACH ROW EXECUTE FUNCTION zc_touch_row();

-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_assessment ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_assessment FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_assessment_tenant ON zc_assessment
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_assessment_response ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_assessment_response FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_assessment_response_tenant ON zc_assessment_response
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_risk_classification ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_risk_classification FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_risk_classification_tenant ON zc_risk_classification
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_assessment_tenant ON zc_assessment;
ALTER TABLE zc_assessment NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_assessment DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_assessment_response_tenant ON zc_assessment_response;
ALTER TABLE zc_assessment_response NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_assessment_response DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_risk_classification_tenant ON zc_risk_classification;
ALTER TABLE zc_risk_classification NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_risk_classification DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON zc_assessment TO zc_app;
GRANT USAGE ON SEQUENCE zc_assessment_id_seq TO zc_app;
GRANT SELECT, INSERT ON zc_assessment_response TO zc_app;
REVOKE UPDATE, DELETE, TRUNCATE ON zc_assessment_response FROM zc_app;
GRANT USAGE ON SEQUENCE zc_assessment_response_id_seq TO zc_app;
GRANT SELECT, INSERT ON zc_risk_classification TO zc_app;
REVOKE UPDATE, DELETE, TRUNCATE ON zc_risk_classification FROM zc_app;
GRANT USAGE ON SEQUENCE zc_risk_classification_id_seq TO zc_app;

rollback.sql:
REVOKE ALL ON zc_assessment FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_assessment_id_seq FROM zc_app;
REVOKE ALL ON zc_assessment_response FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_assessment_response_id_seq FROM zc_app;
REVOKE ALL ON zc_risk_classification FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_risk_classification_id_seq FROM zc_app;
